{
  "facts": [
    {
      "topic": "configuration",
      "statement": "The harness reads a packed configuration prefix, masks the permitted option bits, and treats the remaining bytes as Markdown. An all-zero prefix selects document parsing with UTF-8 validation disabled.",
      "evidence": [
        {
          "unit_id": "u-01d44c1169261cd79a4c",
          "start_line": 10,
          "end_line": 32,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "The document route passes the Markdown bytes and length to cmark_parse_document, which feeds and finishes a parser.",
      "evidence": [
        {
          "unit_id": "u-01d44c1169261cd79a4c",
          "start_line": 24,
          "end_line": 33,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-16ced6e022a8e3e57bf9",
          "start_line": 561,
          "end_line": 569,
          "role": "dependency",
          "dependency_reason": "This is the implementation called by the harness's document route."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "trigger",
      "statement": "When CMARK_OPT_VALIDATE_UTF8 is clear, line processing copies the supplied bytes into the parser's line buffer, so this stage does not replace an interior 0xFF byte.",
      "evidence": [
        {
          "unit_id": "u-aee4c25fb282bf84622c",
          "start_line": 1272,
          "end_line": 1288,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-01d44c1169261cd79a4c",
          "start_line": 16,
          "end_line": 32,
          "role": "dependency",
          "dependency_reason": "A zero configuration prefix supplies options without CMARK_OPT_VALIDATE_UTF8 through the document route."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "The after _scan_at wrapper rejects a null chunk pointer or offset beyond the chunk length. Otherwise it temporarily terminates the chunk, calls the supplied scanner at the offset, restores the byte, and returns the scanner result without a separate high-byte filter.",
      "evidence": [
        {
          "unit_id": "u-02010e4a7ff58ffb27c8",
          "start_line": 6,
          "end_line": 22,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "consequence",
      "statement": "Block parsing calls scan_html_block_start_7 only for a nonindented candidate outside the paragraph and lazy-continuation gates. A nonzero result creates an HTML block and stores that result as its block type.",
      "evidence": [
        {
          "unit_id": "u-aee4c25fb282bf84622c",
          "start_line": 975,
          "end_line": 992,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-aee4c25fb282bf84622c",
          "start_line": 1044,
          "end_line": 1053,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-aee4c25fb282bf84622c",
          "start_line": 1299,
          "end_line": 1313,
          "role": "dependency",
          "dependency_reason": "Line processing passes the prepared chunk into open_new_blocks."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "counterevidence",
      "statement": "The supplied after g0014 fragment shows a return-7 state and quoted-value states using bitmap tests, but does not show enough of the scanner's entry transitions to establish that an attribute containing 0xFF reaches that return.",
      "evidence": [
        {
          "unit_id": "u-27ff36ef636f8bec83a5",
          "start_line": 98,
          "end_line": 100,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-27ff36ef636f8bec83a5",
          "start_line": 119,
          "end_line": 156,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "alternative",
      "statement": "The old harness also offers file and incremental parser routes. Its markdown_to_html route calls cmark_parse_document internally, providing another route to document parsing.",
      "evidence": [
        {
          "unit_id": "u-01d44c1169261cd79a4c",
          "start_line": 35,
          "end_line": 61,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-84446617c1ab4ffb70a7",
          "start_line": 38,
          "end_line": 47,
          "role": "dependency",
          "dependency_reason": "The helper used by mode 3 delegates to document parsing."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "counterevidence",
      "statement": "The complete harness contains no assertion about HTML block type or rendered content. It renders and frees outputs only when doc is nonnull.",
      "evidence": [
        {
          "unit_id": "u-01d44c1169261cd79a4c",
          "start_line": 64,
          "end_line": 75,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": true,
      "audited_unit_ids": [
        "u-01d44c1169261cd79a4c"
      ]
    },
    {
      "topic": "configuration",
      "statement": "The supplied recipe configures CMake, builds cmark_static, then compiles and links the fuzz entry against libcmark.a. It supplies no build or execution result.",
      "evidence": [
        {
          "unit_id": "u-944c463f7c78bc0977c2",
          "start_line": 18,
          "end_line": 25,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    }
  ],
  "missing_information": [
    "This continuation does not supply the complete before and after _scan_html_block_start_7 bodies or the scan_html_block_start_7 macro needed to establish the exact 0xFF scanner path."
  ],
